<?php
require_once dirname(__DIR__).'/includes/functions.php';
$user=require_role('student');
$events=db()->query("SELECT e.*,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status<>'Cancelled') registered FROM events e WHERE e.status='Open' AND e.deleted_at IS NULL AND e.event_date>=CURDATE() ORDER BY e.event_date LIMIT 4")->fetchAll();
$s=db()->prepare("SELECT r.*,e.title,e.event_date,e.venue FROM registrations r JOIN events e ON e.id=r.event_id WHERE r.user_id=? AND r.status<>'Cancelled' ORDER BY e.event_date LIMIT 4");$s->execute([$user['id']]);$registrations=$s->fetchAll();
$pageTitle='Student dashboard';require dirname(__DIR__).'/includes/header.php';
?>
<section class="hero py-5 mb-4"><div class="row align-items-center"><div class="col-lg-8"><p class="text-uppercase small fw-bold opacity-75 mb-2">Your campus, in motion</p><h1 class="display-6 fw-bold">Good to see you, <?=e($user['name'])?>.</h1><p class="lead mb-0">Find your next event and keep your registrations right here.</p></div><div class="col-lg-4 text-lg-end mt-3 mt-lg-0"><a class="btn btn-light btn-lg" href="<?=e(url('student/events.php'))?>">Browse events <i class="bi bi-arrow-right"></i></a></div></div></section>
<div class="row g-3 mb-4"><div class="col-sm-6 col-lg-3"><div class="card p-3"><span class="text-secondary small">Upcoming events</span><div class="metric"><?=count($events)?></div></div></div><div class="col-sm-6 col-lg-3"><div class="card p-3"><span class="text-secondary small">My active registrations</span><div class="metric"><?=count($registrations)?></div></div></div><div class="col-sm-6 col-lg-3"><div class="card p-3"><span class="text-secondary small">Unread notifications</span><div class="metric" id="unread-count"><?=unread_count((int)$user['id'])?></div></div></div></div>
<div class="row g-4"><div class="col-lg-7"><div class="d-flex justify-content-between mb-3"><h2 class="h4 fw-bold">Upcoming events</h2><a href="<?=e(url('student/events.php'))?>">View all</a></div><div class="row g-3"><?php foreach($events as $event):?><div class="col-md-6"><div class="card card-hover h-100"><div class="card-body"><span class="badge text-bg-light"><?=e($event['category'])?></span><h3 class="h5 mt-2"><?=e($event['title'])?></h3><p class="text-secondary small mb-2"><i class="bi bi-calendar3 me-1"></i><?=e(date('M j',strtotime($event['event_date'])))?> · <?=e($event['venue'])?></p><p class="small mb-3"><?=event_seats_left((int)$event['id'],(int)$event['max_participants'])?> seats left</p><a class="btn btn-sm btn-outline-primary" href="<?=e(url('student/register.php?event='.(int)$event['id']))?>">View event</a></div></div></div><?php endforeach;?><?php if(!$events):?><div class="empty-state">No upcoming events have been posted yet.</div><?php endif;?></div></div>
<div class="col-lg-5"><h2 class="h4 fw-bold mb-3">My registrations</h2><?php foreach($registrations as $r):?><div class="card p-3 mb-3"><div class="d-flex justify-content-between"><strong><?=e($r['title'])?></strong><span class="badge <?= $r['status']==='Verified'?'text-bg-success':($r['status']==='Rejected'?'text-bg-danger':'text-bg-warning')?>"><?=e($r['status'])?></span></div><small class="text-secondary mt-1"><?=e(date('M j, Y',strtotime($r['event_date'])))?> · <?=e($r['venue'])?></small><a class="small mt-2" href="<?=e(url('student/my_registrations.php'))?>">View registration</a></div><?php endforeach;?><?php if(!$registrations):?><div class="card empty-state">You haven't registered for an event yet.</div><?php endif;?></div></div>
<?php require dirname(__DIR__).'/includes/footer.php';?>
